/bin/bash -lc ".venv/bin/python - <<'PY'
import json,re,unicodedata
from pathlib import Path

def norm(s):
    s=unicodedata.normalize('NFKD',s or '').encode('ascii','ignore').decode().lower()
    return re.sub(r'["'^a-z0-9]+'"','',s)
bib=Path('workspace/library/references.bib').read_text()
starts=list(re.finditer(r'(?m)"'^@('"\\w+)\\{(["'^,]+),'"',bib))
titles={}
dois={}
for i,m in enumerate(starts):
    block=bib[m.start(): starts[i+1].start() if i+1<len(starts) else len(bib)]
    tm=re.search(r'(?mis)"'^'"\\s*title\\s*=\\s*[{\"](.*?)[}\"]\\s*,?\\s*"'$'"',block)
    dm=re.search(r'(?mis)"'^'"\\s*doi\\s*=\\s*[{\"](.*?)[}\"]\\s*,?\\s*"'$'"',block)
    if tm: titles[norm(tm.group(1))]=m.group(2)
    if dm: dois[norm(dm.group(1))]=m.group(2)
for n,line in enumerate(Path('workspace/library/papers.jsonl').open(),1):
    o=json.loads(line); k=dois.get(norm(o.get('doi'))) or titles.get(norm(o.get('title')))
    if not k: print(f'{n}\\t{o[\"year\"]}\\t{o[\"title\"]}')
PY"

